class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        n = len(nums)
        min_cost = float('inf')

        # Try all possible positions for the first and second split
        # First split after index i (exclusive), second split after index j (exclusive)
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                # Cost is sum of first elements of three subarrays
                cost = nums[0] + nums[i] + nums[j]
                min_cost = min(min_cost, cost)

        return min_cost

class Solution:
    def maxFrequencyElements(self, nums: List[int]) -> int:
        freq = [0] * 101
        maxF = 0

        # Count frequencies and find maximum frequency
        for num in nums:
            freq[num] += 1
            maxF = max(maxF, freq[num])

        # Count total elements with maximum frequency
        ans = 0
        for count in freq:
            if count == maxF:
                ans += count

        return ans

class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        max_diagonal = 0
        max_area = 0

        for length, width in dimensions:
            diagonal = (length * length + width * width) ** 0.5
            area = length * width

            if diagonal > max_diagonal:
                max_diagonal = diagonal
                max_area = area
            elif diagonal == max_diagonal:
                max_area = max(max_area, area)

        return max_area

class Solution:
    def hasTrailingZeros(self, nums: List[int]) -> bool:
        even_count = 0
        for num in nums:
            if num % 2 == 0:
                even_count += 1
        return even_count >= 2

class Solution:
    def numberGame(self, nums: List[int]) -> List[int]:
        nums.sort()
        arr = []
        for i in range(0, len(nums), 2):
            # Bob removes the larger of the two in the pair (at i+1)
            # Alice removes the smaller of the two in the pair (at i)
            arr.append(nums[i + 1])  # Bob appends first
            arr.append(nums[i])      # Alice appends second
        return arr

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Try all possible subarrays to remove
        for i in range(n):
            for j in range(i, n):
                # Check if removing subarray from i to j results in strictly increasing array
                valid = True
                prev = -1  # Previous element in the remaining array

                # Check all elements not in the removed subarray
                for k in range(n):
                    if k < i or k > j:  # Element is not in the removed subarray
                        if prev != -1 and nums[k] <= prev:
                            valid = False
                            break
                        prev = nums[k]

                if valid:
                    count += 1

        return count

class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        freq = [0] * (n * n + 1)

        # Count frequency of each number
        for i in range(n):
            for j in range(n):
                freq[grid[i][j]] += 1

        # Find the repeated and missing numbers
        repeated = 0
        missing = 0
        for i in range(1, n * n + 1):
            if freq[i] == 2:
                repeated = i
            elif freq[i] == 0:
                missing = i

        return [repeated, missing]

