class Solution:
    def findIntersectionValues(self, nums1: List[int], nums2: List[int]) -> List[int]:
        # Convert nums2 to a set for O(1) lookup
        set_nums2 = set(nums2)
        # Count elements in nums1 that exist in nums2
        c1 = 0
        for num in nums1:
            if num in set_nums2:
                c1 += 1

        # Convert nums1 to a set for O(1) lookup
        set_nums1 = set(nums1)
        # Count elements in nums2 that exist in nums1
        c2 = 0
        for num in nums2:
            if num in set_nums1:
                c2 += 1

        return [c1, c2]

