class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        min_len = min(len(s1), len(s2), len(s3))
        common_prefix_len = 0

        for i in range(min_len):
            if s1[i] == s2[i] == s3[i]:
                common_prefix_len += 1
            else:
                break

        if common_prefix_len == 0:
            return -1

        return (len(s1) - common_prefix_len) + (len(s2) - common_prefix_len) + (len(s3) - common_prefix_len)

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        maxXor = 0
        n = len(nums)

        for i in range(n):
            for j in range(i, n):
                x, y = nums[i], nums[j]
                if abs(x - y) <= min(x, y):
                    maxXor = max(maxXor, x ^ y)

        return maxXor

class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        ans = 0
        for c1 in range(limit + 1):
            for c2 in range(limit + 1):
                c3 = n - c1 - c2
                if c3 >= 0 and c3 <= limit:
                    ans += 1
        return ans

class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        n = len(grid)

        for i in range(n):
            isChampion = True
            for j in range(n):
                if i != j and grid[j][i] == 1:
                    isChampion = False
                    break
            if isChampion:
                return i

        return -1

class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        result = 0
        # Check each bit position from 0 to 31
        for bit in range(32):
            count = 0
            # Count how many numbers have the current bit set
            for num in nums:
                if (num >> bit) & 1:
                    count += 1
            # If at least k numbers have this bit set, set it in result
            if count >= k:
                result |= (1 << bit)
        return result

class Solution:
    def sumCounts(self, nums: List[int]) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            distinct = set()
            for j in range(i, n):
                distinct.add(nums[j])
                total_sum += len(distinct) ** 2

        return total_sum

class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        ans = float('inf')

        # Check all possible triplets (i, j, k) where i < j < k
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    # Check if it forms a mountain triplet
                    if nums[i] < nums[j] and nums[k] < nums[j]:
                        # Update minimum sum
                        ans = min(ans, nums[i] + nums[j] + nums[k])

        # Return -1 if no valid triplet found, otherwise return minimum sum
        return ans if ans != float('inf') else -1

class Solution:
    def findIndices(self, nums: List[int], indexDifference: int, valueDifference: int) -> List[int]:
        n = len(nums)

        for i in range(n):
            for j in range(n):
                if abs(i - j) >= indexDifference and abs(nums[i] - nums[j]) >= valueDifference:
                    return [i, j]

        return [-1, -1]

class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        nums = []
        result = []
        consecutive_prev = 0

        for word in words:
            if word == "prev":
                consecutive_prev += 1
                k = consecutive_prev
                if k > len(nums):
                    result.append(-1)
                else:
                    result.append(nums[-k])
            else:
                nums.append(int(word))
                consecutive_prev = 0

        return result

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        collected = set()
        operations = 0

        # Iterate from right to left
        for i in range(len(nums) - 1, -1, -1):
            collected.add(nums[i])
            operations += 1

            # Check if we have collected all elements from 1 to k
            if all(x in collected for x in range(1, k + 1)):
                return operations

        return operations

