class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)

        # Check if already sorted
        if all(nums[i] < nums[i + 1] for i in range(n - 1)):
            return 0

        # Find the break point where nums[i] > nums[i+1]
        break_point = -1
        for i in range(n - 1):
            if nums[i] > nums[i + 1]:
                if break_point != -1:  # More than one break point
                    return -1
                break_point = i

        # Check if the array can be sorted by right shifts
        # The break point should be the last element of the sorted array
        # and the first element should be greater than the last element
        if break_point == -1:
            return -1

        # Check if the array is sorted after right shifting
        # The suffix starting from break_point + 1 should be sorted and
        # the last element should be less than the first element
        if nums[break_point + 1] > nums[0]:
            return -1

        # Check if the suffix is sorted
        for i in range(break_point + 1, n - 1):
            if nums[i] > nums[i + 1]:
                return -1

        # Check if the prefix is sorted
        for i in range(break_point):
            if nums[i] > nums[i + 1]:
                return -1

        # Check if the last element of suffix is less than first element of prefix
        if nums[n - 1] > nums[0]:
            return -1

        return n - break_point - 1

class Solution:
    def numberOfPoints(self, nums: List[List[int]]) -> int:
