class Solution:
    def furthestDistanceFromOrigin(self, moves: str) -> int:
        count_L = moves.count('L')
        count_R = moves.count('R')
        count_ = moves.count('_')

        # If we replace all '_' with the direction that has more occurrences,
        # we get the maximum distance
        if count_L >= count_R:
            # Replace all '_' with 'L'
            total_displacement = count_L + count_ - count_R
        else:
            # Replace all '_' with 'R'
            total_displacement = count_R + count_ - count_L

        return abs(total_displacement)

class Solution:
    def isAcronym(self, words: List[str], s: str) -> bool:
        if len(s) != len(words):
            return False

        acronym = ""
        for word in words:
            acronym += word[0]

        return acronym == s

class Solution:
    def countPairs(self, nums: List[int], target: int) -> int:
        nums.sort()
        left = 0
        right = len(nums) - 1
        count = 0

        while left < right:
            if nums[left] + nums[right] < target:
                count += right - left
                left += 1
            else:
                right -= 1

        return count

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Dictionary to group numbers by their maximum digit
        digit_groups = {}

        # Function to find the maximum digit in a number
        def max_digit(num):
            return max(int(digit) for digit in str(num))

        # Group numbers by their maximum digit
        for num in nums:
            max_dig = max_digit(num)
            if max_dig not in digit_groups:
                digit_groups[max_dig] = []
            digit_groups[max_dig].append(num)

        max_sum = -1

        # For each group with at least 2 numbers, find the maximum sum of a pair
        for digit, numbers in digit_groups.items():
            if len(numbers) >= 2:
                # Sort the numbers in descending order and take the two largest
                numbers.sort(reverse=True)
                current_sum = numbers[0] + numbers[1]
                max_sum = max(max_sum, current_sum)

        return max_sum

