class Solution:
    def splitWordsBySeparator(self, words: List[str], separator: str) -> List[str]:
        result = []
        for word in words:
            # Split the word by the separator and filter out empty strings
            substrings = [s for s in word.split(separator) if s]
            # Add the non-empty substrings to the result
            result.extend(substrings)
        return result

class Solution:
    def isGood(self, nums: List[int]) -> bool:
        # Step 1: Find the maximum element to determine candidate n
        n = max(nums)

        # Step 2: Check if the length of the array is n + 1
        if len(nums) != n + 1:
            return False

        # Step 3: Use a frequency counter to count occurrences of each number
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Step 4: Verify that numbers 1 to n-1 appear exactly once
        for i in range(1, n):
            if freq.get(i, 0) != 1:
                return False

        # Step 5: Verify that the number n appears exactly twice
        if freq.get(n, 0) != 2:
            return False

        # Step 6: All conditions are satisfied
        return True

