class Solution:
    def alternatingSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        max_length = -1

        for i in range(n - 1):
            # Check if current element can be the start of an alternating subarray
            if nums[i + 1] == nums[i] + 1:
                # Start extending the subarray from index i
                length = 2
                j = i + 2
                while j < n:
                    # Check alternating pattern: even positions should be nums[i], odd positions should be nums[i+1]
                    if (j - i) % 2 == 0 and nums[j] == nums[i]:
                        length += 1
                    elif (j - i) % 2 == 1 and nums[j] == nums[i + 1]:
                        length += 1
                    else:
                        break
                    j += 1
                max_length = max(max_length, length)

        return max_length

class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        # Group numbers by their number of set bits
        groups = {}
        for num in nums:
            # Count number of set bits
            bits = bin(num).count('1')
            if bits not in groups:
                groups[bits] = []
            groups[bits].append(num)

        # Sort each group
        for bits in groups:
            groups[bits].sort()

        # Get the set bit counts in sorted order
        bit_counts = sorted(groups.keys())

        # Check if the maximum of each group is <= minimum of the next group
        for i in range(len(bit_counts) - 1):
            current_bits = bit_counts[i]
            next_bits = bit_counts[i + 1]

            # Check if max of current group <= min of next group
            if groups[current_bits][-1] > groups[next_bits][0]:
                return False

        return True

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        current_xor = 0
        for num in nums:
            current_xor ^= num

        # XOR current_xor with k to find differing bits
        diff = current_xor ^ k

        # Count the number of set bits in diff
        return bin(diff).count('1')

from collections import deque

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        queue = deque([(x, 0)])
        visited = {x}

        while queue:
            current, steps = queue.popleft()

            # Generate next possible states
            next_states = []

            # Increment
            next_states.append(current + 1)
            # Decrement
            next_states.append(current - 1)
            # Divide by 11 if divisible
            if current % 11 == 0:
                next_states.append(current // 11)
            # Divide by 5 if divisible
            if current % 5 == 0:
                next_states.append(current // 5)

            for next_state in next_states:
                if next_state == y:
                    return steps + 1

                if next_state not in visited and 1 <= next_state <= 10000:
                    visited.add(next_state)
                    queue.append((next_state, steps + 1))

        return -1  # Should not reach here given constraints

class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        # Group lengths of consecutive characters
        char_groups = defaultdict(list)
        i = 0
        n = len(s)

        while i < n:
            char = s[i]
            count = 0
            while i < n and s[i] == char:
                count += 1
                i += 1
            char_groups[char].append(count)

        max_length = -1

        # For each character, check possible lengths
        for char, lengths in char_groups.items():
            # Count frequency of each possible substring length
            length_count = defaultdict(int)

            for length in lengths:
                # A block of length 'length' contributes (length - l + 1) substrings of length l
                for l in range(1, length + 1):
                    if length - l + 1 > 0:
                        length_count[l] += (length - l + 1)

            # Find the maximum length that appears at least 3 times
            for l in range(1, max(lengths) + 1):
                if length_count[l] >= 3:
                    max_length = max(max_length, l)

        return max_length

class Solution:
    def largestPerimeter(self, nums: List[int]) -> int:
        nums.sort()
        total_sum = sum(nums)

        # Iterate from the largest element to the smallest
        for i in range(len(nums) - 1, 1, -1):
            # Check if the current element can be the longest side
            if nums[i] < total_sum - nums[i]:
                return total_sum
            # Remove the current element from the total sum
            total_sum -= nums[i]

        return -1

class Solution:
    def divideArray(self, nums: List[int], k: int) -> List[List[int]]:
        nums.sort()
        result = []

        for i in range(0, len(nums), 3):
            # Check if the difference between the largest and smallest in the triplet exceeds k
            if nums[i + 2] - nums[i] > k:
                return []
            # Add the triplet to the result
            result.append([nums[i], nums[i + 1], nums[i + 2]])

        return result

class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def is_palindrome(num):
            s = str(num)
            return s == s[::-1]

        def generate_palindromes_in_range(low, high):
            palindromes = set()
            # Generate palindromes with 1 to 9 digits
            for digits in range(1, 10):
                if digits == 1:
                    for d in range(1, 10):
                        if low <= d <= high:
                            palindromes.add(d)
                elif digits == 2:
                    for d1 in range(1, 10):
                        d2 = d1
                        num = d1 * 10 + d2
                        if low <= num <= high:
                            palindromes.add(num)
                elif digits == 3:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            num = d1 * 100 + d2 * 10 + d1
                            if low <= num <= high:
                                palindromes.add(num)
                elif digits == 4:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            num = d1 * 1000 + d2 * 100 + d2 * 10 + d1
                            if low <= num <= high:
                                palindromes.add(num)
                elif digits == 5:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            for d3 in range(10):
                                num = d1 * 10000 + d2 * 1000 + d3 * 100 + d2 * 10 + d1
                                if low <= num <= high:
                                    palindromes.add(num)
                elif digits == 6:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            for d3 in range(10):
                                num = d1 * 100000 + d2 * 10000 + d3 * 1000 + d3 * 100 + d2 * 10 + d1
                                if low <= num <= high:
                                    palindromes.add(num)
                elif digits == 7:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            for d3 in range(10):
                                num = d1 * 1000000 + d2 * 100000 + d3 * 10000 + d3 * 1000 + d2 * 100 + d1 * 10 + d1
                                if low <= num <= high:
                                    palindromes.add(num)
                elif digits == 8:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            for d3 in range(10):
                                for d4 in range(10):
                                    num = d1 * 10000000 + d2 * 1000000 + d3 * 100000 + d4 * 10000 + d4 * 1000 + d3 * 100 + d2 * 10 + d1
                                    if low <= num <= high:
                                        palindromes.add(num)
                elif digits == 9:
                    for d1 in range(1, 10):
                        for d2 in range(10):
                            for d3 in range(10):
                                for d4 in range(10):
                                    num = d1 * 100000000 + d2 * 10000000 + d3 * 1000000 + d4 * 100000 + d4 * 10000 + d3 * 1000 + d2 * 100 + d1 * 10 + d1
                                    if low <= num <= high:
                                        palindromes.add(num)
            return palindromes

        nums.sort()
        n = len(nums)
        median = nums[n // 2] if n % 2 == 1 else (nums[n // 2 - 1] + nums[n // 2]) // 2

        # Generate palindromes around the median
        low_bound = max(1, median - 1000)
        high_bound = min(10**9 - 1, median + 1000)

        palindromes = generate_palindromes_in_range(low_bound, high_bound)

        min_cost = float('inf')
        for p in palindromes:
            cost = sum(abs(num - p) for num in nums)
            min_cost = min(min_cost, cost)

        return min_cost

class Solution:
    def getGoodIndices(self, variables: List[List[int]], target: int) -> List[int]:
        result = []

        for i, (a, b, c, m) in enumerate(variables):
            # Calculate a^b % 10 using modular exponentiation
            power_mod_10 = pow(a, b, 10)
            # Calculate (a^b % 10)^c % m using modular exponentiation
            result_mod_m = pow(power_mod_10, c, m)

            # Check if the result matches the target
            if result_mod_m == target:
                result.append(i)

        return result

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        max_val = max(nums)
        left = 0
        count = 0
        result = 0

        for right in range(len(nums)):
            if nums[right] == max_val:
                count += 1

            while count >= k:
                result += len(nums) - right
                if nums[left] == max_val:
                    count -= 1
                left += 1

        return result

class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        def is_almost_equal(a, b):
            return a == b or abs(ord(a) - ord(b)) == 1

        ans = 0
        i = 1
        while i < len(word):
            if is_almost_equal(word[i], word[i-1]):
                ans += 1
                i += 2  # Skip the next character to avoid creating new almost-equal pairs
            else:
                i += 1

        return ans

class Solution:
    def maxSubarrayLength(self, nums: List[int], k: int) -> int:
        left = 0
        max_length = 0
        freq = {}

        for right in range(len(nums)):
            # Add current element to frequency dictionary
            freq[nums[right]] = freq.get(nums[right], 0) + 1

            # If frequency of current element exceeds k, contract window
            while freq[nums[right]] > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    del freq[nums[left]]
                left += 1

            # Update maximum length
            max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        max_sofar = 0
        ans = 0

        for coin in coins:
            while max_sofar + 1 < coin:
                max_sofar += max_sofar + 1
                ans += 1
            max_sofar += coin

        while max_sofar < target:
            max_sofar += max_sofar + 1
            ans += 1

        return ans

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(s)
        # Prefix sum arrays for vowels and consonants
        cnt_0 = [0] * (n + 1)  # vowels count
        cnt_1 = [0] * (n + 1)  # consonants count

        # Fill prefix sum arrays
        for i in range(n):
            if s[i] in vowels:
                cnt_0[i + 1] = cnt_0[i] + 1
                cnt_1[i + 1] = cnt_1[i]
            else:
                cnt_0[i + 1] = cnt_0[i]
                cnt_1[i + 1] = cnt_1[i] + 1

        res = 0

        # Check all substrings
        for i in range(n):
            for j in range(i + 1, n + 1):
                vowels_count = cnt_0[j] - cnt_0[i]
                consonants_count = cnt_1[j] - cnt_1[i]

                # Check if vowels == consonants and their product is divisible by k
                if vowels_count == consonants_count and (vowels_count * consonants_count) % k == 0:
                    res += 1

        return res

class Solution:
    def maximizeSquareHoleArea(self, n: int, m: int, hBars: List[int], vBars: List[int]) -> int:
        def find_longest_consecutive(bars):
            bars.sort()
            max_consecutive = 1
            current_consecutive = 1

            for i in range(1, len(bars)):
                if bars[i] == bars[i-1] + 1:
                    current_consecutive += 1
                else:
                    max_consecutive = max(max_consecutive, current_consecutive)
                    current_consecutive = 1

            return max(max_consecutive, current_consecutive)

        max_h_consecutive = find_longest_consecutive(hBars)
        max_v_consecutive = find_longest_consecutive(vBars)

        # The maximum side length of the square hole is the minimum of the longest consecutive sequences
        # in horizontal and vertical bars, plus 1 (since removing k consecutive bars creates k+1 gaps)
        max_side = min(max_h_consecutive, max_v_consecutive) + 1

        # The area of the square is the square of the side length
        return max_side * max_side

class Solution:
    def minimumSteps(self, s: str) -> int:
        total_white = s.count('0')
        white_seen = 0
        ans = 0

        for char in s:
            if char == '0':
                white_seen += 1
            else:
                # This black ball needs to move past all white balls to its right
                ans += total_white - white_seen

        return ans

class Solution:
    def findChampion(self, n: int, edges: List[List[int]]) -> int:
        # Initialize a set with all teams
        winner = set(range(n))

        # For each edge [u, v], remove the weaker team v from the winner set
        for u, v in edges:
            if v in winner:
                winner.remove(v)

        # If there is exactly one team left, return it; otherwise return -1
        return list(winner)[0] if len(winner) == 1 else -1

class Solution:
    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        sum1 = 0
        sum2 = 0
        cnt1 = 0
        cnt2 = 0

        for num in nums1:
            if num == 0:
                cnt1 += 1
            else:
                sum1 += num

        for num in nums2:
            if num == 0:
                cnt2 += 1
            else:
                sum2 += num

        # If both arrays have no zeros
        if cnt1 == 0 and cnt2 == 0:
            return sum1 if sum1 == sum2 else -1

        # If nums1 has no zeros but nums2 has zeros
        if cnt1 == 0 and cnt2 > 0:
            # We need sum1 >= sum2 + cnt2 (since each zero in nums2 must be replaced by at least 1)
            if sum1 >= sum2 + cnt2:
                return sum1
            else:
                return -1

        # If nums2 has no zeros but nums1 has zeros
        if cnt2 == 0 and cnt1 > 0:
            # We need sum2 >= sum1 + cnt1 (since each zero in nums1 must be replaced by at least 1)
            if sum2 >= sum1 + cnt1:
                return sum2
            else:
                return -1

        # Both arrays have zeros
        # We can achieve the minimum equal sum as max(sum1 + cnt1, sum2 + cnt2)
        return max(sum1 + cnt1, sum2 + cnt2)

class Solution:
    def minChanges(self, s: str) -> int:
        changes = 0
        n = len(s)
        for i in range(0, n, 2):
            if s[i] != s[i + 1]:
                changes += 1
        return changes

class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        m = len(grid[0])
        MOD = 12345

        # Count zeros and compute total product
        zero_count = 0
        total_product = 1

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 0:
                    zero_count += 1
                else:
                    total_product = (total_product * grid[i][j]) % MOD

        # If more than one zero, all products will be 0
        if zero_count > 1:
            return [[0] * m for _ in range(n)]

        # If exactly one zero, only the zero position will have non-zero product
        if zero_count == 1:
            result = [[0] * m for _ in range(n)]
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == 0:
                        result[i][j] = total_product
            return result

        # No zeros, use prefix and suffix products
        result = [[0] * m for _ in range(n)]

        # First pass: compute prefix products
        prefix = 1
        for i in range(n):
            for j in range(m):
                result[i][j] = prefix
                prefix = (prefix * grid[i][j]) % MOD

        # Second pass: compute suffix products and combine with prefix
        suffix = 1
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                result[i][j] = (result[i][j] * suffix) % MOD
                suffix = (suffix * grid[i][j]) % MOD

        return result

class Solution:
    def getWordsInLongestSubsequence(self, n: int, words: List[str], groups: List[int]) -> List[str]:
        result = [words[0]]
        current_group = groups[0]

        for i in range(1, n):
            if groups[i] != current_group:
                result.append(words[i])
                current_group = groups[i]

        return result

class Solution:
    def maxSubarrays(self, nums: List[int]) -> int:
        # Calculate the overall AND of the entire array
        overall_and = nums[0]
        for i in range(1, len(nums)):
            overall_and &= nums[i]

        # If the overall AND is non-zero, we cannot get a score of 0
        # So we must have only one subarray
        if overall_and != 0:
            return 1

        # If overall AND is 0, we can try to split into multiple subarrays with score 0
        # Use greedy approach: form subarrays ending when current AND becomes 0
        count = 0
        current_and = -1  # Start with all bits set (equivalent to 2^32 - 1 for 32-bit integers)

        for num in nums:
            if current_and == -1:
                current_and = num
            else:
                current_and &= num

            # If current AND becomes 0, we can end a subarray here
            if current_and == 0:
                count += 1
                current_and = -1  # Reset for next subarray

        # If we couldn't form any subarray with score 0, return 1
        # (this happens when no subarray can achieve AND 0)
        return max(1, count)

class Solution:
    def countWays(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        count = 0

        for k in range(n + 1):
            # Count students with nums[i] < k
            # These students must be selected
            selected_count = 0
            for num in nums:
                if num < k:
                    selected_count += 1
                else:
                    break

            # Check if the number of students with nums[i] < k equals k
            if selected_count == k:
                # Check if any student has nums[i] == k
                # If yes, then it's impossible because:
                # - If selected: k > nums[i] fails (k == nums[i])
                # - If not selected: k < nums[i] fails (k == nums[i])
                has_equal = False
                for num in nums:
                    if num == k:
                        has_equal = True
                        break

                if not has_equal:
                    count += 1

        return count

class Solution:
    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        left = 0
        right = n // 2
        pairs = 0

        while left < n // 2 and right < n:
            if nums[left] < nums[right]:
                pairs += 1
                left += 1
                right += 1
            else:
                right += 1

        return n - 2 * pairs

class Solution:
    def isReachableAtTime(self, sx: int, sy: int, fx: int, fy: int, t: int) -> bool:
        # Calculate Chebyshev distance
        distance = max(abs(fx - sx), abs(fy - sy))

        # If start and end are the same
        if distance == 0:
            return t != 1

        # If time is sufficient to reach the destination
        return t >= distance

class Solution:
    def checkStrings(self, s1: str, s2: str) -> bool:
        if len(s1) != len(s2):
            return False

        even1 = []
        odd1 = []
        even2 = []
        odd2 = []

        for i in range(len(s1)):
            if i % 2 == 0:
                even1.append(s1[i])
                even2.append(s2[i])
            else:
                odd1.append(s1[i])
                odd2.append(s2[i])

        even1.sort()
        even2.sort()
        odd1.sort()
        odd2.sort()

        return even1 == even2 and odd1 == odd2

class Solution:
    def maxSum(self, nums: List[int], m: int, k: int) -> int:
        n = len(nums)
        if n < k:
            return 0

        # Initialize variables
        left = 0
        current_sum = 0
        freq = {}
        max_sum = 0

        # Slide the window of size k
        for right in range(n):
            # Add current element to window
            current_sum += nums[right]
            freq[nums[right]] = freq.get(nums[right], 0) + 1

            # If window size exceeds k, remove leftmost element
            if right - left + 1 > k:
                current_sum -= nums[left]
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    del freq[nums[left]]
                left += 1

            # Check if window size is exactly k and has at least m distinct elements
            if right - left + 1 == k and len(freq) >= m:
                max_sum = max(max_sum, current_sum)

        return max_sum

class Solution:
    def minimumPossibleSum(self, n: int, target: int) -> int:
        MOD = 10**9 + 7
        k = target // 2

        if n <= k:
            return (n * (n + 1) // 2) % MOD
        else:
            sum1 = k * (k + 1) // 2
            sum2 = (n - k) * (2 * target + (n - k - 1)) // 2
            return (sum1 + sum2) % MOD

class Solution:
    def minimumSum(self, n: int, k: int) -> int:
        selected = set()
        num = 1
        total_sum = 0

        while len(selected) < n:
            if (k - num) not in selected:
                selected.add(num)
                total_sum += num
            num += 1

        return total_sum

class Solution:
    def maximizeTheProfit(self, n: int, offers: List[List[int]]) -> int:
        # Group offers by their end position
        groups = [[] for _ in range(n)]
        for start, end, gold in offers:
            groups[end].append((start, gold))

        # DP array where f[i] represents maximum gold up to position i
        f = [0] * (n + 1)

        for i in range(n):
            # Option 1: Don't take any offer ending at position i
            f[i + 1] = f[i]

            # Option 2: Take one or more offers ending at position i
            for start, gold in groups[i]:
                f[i + 1] = max(f[i + 1], f[start] + gold)

        return f[n]

class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        # Store indices of each element
        indices = {}
        for i, num in enumerate(nums):
            if num not in indices:
                indices[num] = []
            indices[num].append(i)

        max_length = 0

        # For each unique element, find the longest subarray
        for num in indices:
            pos = indices[num]
            if not pos:
                continue

            # Use sliding window on the positions of current element
            left = 0
            deletions = 0

            for right in range(len(pos)):
                # Calculate deletions needed to make all elements in window equal
                # Deletions = (last index - first index + 1) - (number of elements in window)
                if right > 0:
                    deletions = pos[right] - pos[left] + 1 - (right - left + 1)

                # If deletions exceed k, move left pointer
                while deletions > k:
                    left += 1
                    if left <= right:
                        deletions = pos[right] - pos[left] + 1 - (right - left + 1)

                # Update max length
                max_length = max(max_length, right - left + 1)

        return max_length

class Solution:
    def canMakeSubsequence(self, str1: str, str2: str) -> bool:
        i, j = 0, 0
        n, m = len(str1), len(str2)

        while i < n and j < m:
            # Check if str2[j] can be matched with str1[i] either directly or by incrementing
            if str2[j] == str1[i] or (str1[i] == 'z' and str2[j] == 'a') or (str1[i] != 'z' and str2[j] == chr(ord(str1[i]) + 1)):
                j += 1
            i += 1

        return j == m

class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        if n <= 2:
            return True

        for i in range(n - 1):
            if nums[i] + nums[i + 1] >= m:
                return True

        return False

class Solution:
    def minimumSeconds(self, nums: List[int]) -> int:
        # Dictionary to store indices of each value
        indices = {}
        n = len(nums)

        # Store indices of each value
        for i in range(n):
            if nums[i] not in indices:
                indices[nums[i]] = []
            indices[nums[i]].append(i)

        # If all elements are already equal, return 0
        if len(indices) == 1:
            return 0

        min_seconds = float('inf')

        # For each unique value, calculate the maximum gap
        for value, pos in indices.items():
            max_gap = 0
            # Calculate gaps between consecutive occurrences
            for i in range(len(pos)):
                # Gap between current and next occurrence
                if i == len(pos) - 1:
                    # Wrap-around case: from last occurrence to first occurrence
                    gap = (pos[0] + n) - pos[i]
                else:
                    # Normal case: between consecutive occurrences
                    gap = pos[i + 1] - pos[i]
                max_gap = max(max_gap, gap)

            # The number of seconds needed is ceil(max_gap / 2)
            seconds = (max_gap + 1) // 2
            min_seconds = min(min_seconds, seconds)

        return min_seconds

class Solution:
    def maxArrayValue(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        # Start from the second last element and move backwards
        max_val = nums[-1]
        current_sum = nums[-1]

        for i in range(n - 2, -1, -1):
            # If current element can be merged with the next accumulated sum
            if nums[i] <= current_sum:
                current_sum += nums[i]
            else:
                # Reset current_sum to current element if we can't merge
                current_sum = nums[i]

            # Update maximum value
            max_val = max(max_val, current_sum)

        return max_val

class Solution:
    def sortVowels(self, s: str) -> str:
        vowels = set('aeiouAEIOU')
        vowel_list = []

        # Extract vowels from the string
        for char in s:
            if char in vowels:
                vowel_list.append(char)

        # Sort vowels in non-decreasing order of ASCII values
        vowel_list.sort()

        # Build the result string
        result = []
        vowel_index = 0

        for char in s:
            if char in vowels:
                result.append(vowel_list[vowel_index])
                vowel_index += 1
            else:
                result.append(char)

        return ''.join(result)

class Solution:
    def maxScore(self, nums: List[int], x: int) -> int:
        # Initialize the maximum scores ending with even and odd parity
        lastEven = lastOdd = nums[0]

        # If the first number is even, set lastEven, otherwise set lastOdd
        if nums[0] % 2 == 0:
            lastEven = nums[0]
            lastOdd = nums[0] - x
        else:
            lastEven = nums[0] - x
            lastOdd = nums[0]

        # Iterate through the array starting from index 1
        for i in range(1, len(nums)):
            if nums[i] % 2 == 0:
                # Current number is even
                # Can extend from previous even (no cost) or previous odd (cost x)
                lastEven = max(lastEven + nums[i], lastOdd + nums[i] - x)
            else:
                # Current number is odd
                # Can extend from previous odd (no cost) or previous even (cost x)
                lastOdd = max(lastOdd + nums[i], lastEven + nums[i] - x)

        # Return the maximum score achievable
        return max(lastEven, lastOdd)

class Solution:
    def maximumBeauty(self, nums: List[int], k: int) -> int:
        nums.sort()
        left = 0
        ans = 0

        for right in range(len(nums)):
            # Shrink the window from the left if the condition is not satisfied
            while nums[left] + k < nums[right] - k:
                left += 1

            # Update the maximum beauty
            ans = max(ans, right - left + 1)

        return ans

class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # dp[i] represents the maximum number of jumps to reach index i
        dp = [-1] * n
        # Base case: no jumps needed to reach index 0
        dp[0] = 0

        # Fill the dp array from left to right
        for i in range(1, n):
            # Check all previous indices j to see if we can jump from j to i
            for j in range(i):
                # Check if jump from j to i is valid (within target range)
                if -target <= nums[i] - nums[j] <= target:
                    # If j is reachable and we can jump from j to i
                    if dp[j] != -1:
                        # Update dp[i] with maximum jumps
                        dp[i] = max(dp[i], dp[j] + 1)

        # Return the maximum jumps to reach last index, or -1 if unreachable
        return dp[n-1]

class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        # dp1[i] = max length ending at i with nums1[i]
        # dp2[i] = max length ending at i with nums2[i]
        dp1, dp2 = 1, 1
        max_length = 1

        for i in range(1, n):
            new_dp1, new_dp2 = 1, 1

            # For nums1[i]
            if nums1[i] >= nums1[i-1]:
                new_dp1 = max(new_dp1, dp1 + 1)
            if nums1[i] >= nums2[i-1]:
                new_dp1 = max(new_dp1, dp2 + 1)

            # For nums2[i]
            if nums2[i] >= nums1[i-1]:
                new_dp2 = max(new_dp2, dp1 + 1)
            if nums2[i] >= nums2[i-1]:
                new_dp2 = max(new_dp2, dp2 + 1)

            dp1, dp2 = new_dp1, new_dp2
            max_length = max(max_length, dp1, dp2)

        return max_length

class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        arr = [0] * (n + 1)
        h = 0

        for i in range(n):
            h -= arr[i]
            if nums[i] > h:
                if i + k > n:
                    return False
                arr[i + k] += nums[i] - h
                h = nums[i]
            elif nums[i] < h:
                return False

        return True

class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        # Initialize a set with the initial positions of marbles
        occupied = set(nums)

        # Process each move
        for i in range(len(moveFrom)):
            from_pos = moveFrom[i]
            to_pos = moveTo[i]

            # If the from position is occupied, move marbles to the to position
            if from_pos in occupied:
                occupied.remove(from_pos)
                occupied.add(to_pos)

        # Return the sorted list of occupied positions
        return sorted(list(occupied))

class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        # Precompute all powers of 5 in binary form up to the maximum possible length
        powers_of_5 = set()
        power = 1
        while len(bin(power)[2:]) <= len(s):
            powers_of_5.add(bin(power)[2:])
            power *= 5

        n = len(s)
        # dp[i] represents the minimum number of beautiful substrings for first i characters
        dp = [float('inf')] * (n + 1)
        dp[0] = 0  # Base case: 0 characters need 0 substrings

        for i in range(n):
            if s[i] == '0':
                continue  # No beautiful substring can start with '0'

            for j in range(i, n):
                substring = s[i:j+1]
                # Check if substring is beautiful (no leading zeros and is power of 5)
                if substring in powers_of_5:
                    dp[j+1] = min(dp[j+1], dp[i] + 1)

        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def countBlackBlocks(self, m: int, n: int, coordinates: List[List[int]]) -> List[int]:
        # Convert coordinates to a set for O(1) lookup
        black_cells = set(tuple(coord) for coord in coordinates)

        # Dictionary to store count of black cells in each 2x2 block
        block_count = {}

        # Iterate through all possible 2x2 blocks (top-left corners)
        for i in range(m - 1):
            for j in range(n - 1):
                # Count black cells in this 2x2 block
                count = 0
                # Check the four cells of the block
                if (i, j) in black_cells:
                    count += 1
                if (i + 1, j) in black_cells:
                    count += 1
                if (i, j + 1) in black_cells:
                    count += 1
                if (i + 1, j + 1) in black_cells:
                    count += 1

                # Store the count for this block
                block_count[(i, j)] = count

        # Initialize result array
        result = [0] * 5

        # Count blocks with exactly i black cells
        for count in block_count.values():
            if count <= 4:
                result[count] += 1

        return result

class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        if n < 4:
            return []

        # Sieve of Eratosthenes to find all primes up to n
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False

        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                for j in range(i*i, n + 1, i):
                    is_prime[j] = False

        # Convert to set for O(1) lookup
        primes = set()
        for i in range(2, n + 1):
            if is_prime[i]:
                primes.add(i)

        # Find prime pairs
        result = []
        for x in range(2, n // 2 + 1):
            y = n - x
            if x in primes and y in primes and x <= y:
                result.append([x, y])

        return result

class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        def count_up_to(n):
            if n < 0:
                return 0
            s_n = str(n)
            len_n = len(s_n)
            len_s = len(s)

            # If s is longer than n, no number can have s as suffix
            if len_s > len_n:
                return 0

            # Memoization
            memo = {}

            def dp(pos, tight, started, suffix_pos):
                # Base case: we've processed all digits
                if pos == len_n:
                    # We need to have matched the suffix completely
                    return 1 if suffix_pos == len_s else 0

                if (pos, tight, started, suffix_pos) in memo:
                    return memo[(pos, tight, started, suffix_pos)]

                # Determine the upper limit for current digit
                upper = int(s_n[pos]) if tight else 9
                upper = min(upper, limit)

                result = 0
                for digit in range(0, upper + 1):
                    new_tight = tight and (digit == upper)
                    new_started = started or (digit > 0)
                    new_suffix_pos = suffix_pos

                    # Check if we're in the suffix region
                    if pos >= len_n - len_s:
                        # Calculate the position in the suffix
                        suffix_idx = pos - (len_n - len_s)
                        # Check if digit matches the corresponding suffix digit
                        if digit != int(s[suffix_idx]):
                            continue
                        # We've matched this digit in the suffix
                        new_suffix_pos = suffix_idx + 1

                    # If we're not in the suffix region, we can place any digit <= limit
                    # But we need to handle leading zeros properly
                    if pos < len_n - len_s:
                        # We can place any digit, but we need to track if we've started
                        # (non-zero digit has been placed)
                        if digit == 0 and not started:
                            # Leading zero, continue
                            result += dp(pos + 1, new_tight, False, suffix_pos)
                        else:
                            result += dp(pos + 1, new_tight, new_started, suffix_pos)
                    else:
                        # In suffix region, we've already checked the digit matches
                        result += dp(pos + 1, new_tight, new_started, new_suffix_pos)

                memo[(pos, tight, started, suffix_pos)] = result
                return result

            return dp(0, True, False, 0)

        # Count powerful integers from 0 to finish, subtract count from 0 to start-1
        return count_up_to(finish) - count_up_to(start - 1)

class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        MOD = 10**9 + 7

        # Store the last occurrence index of each number
        last_occurrence = {}
        for i, x in enumerate(nums):
            last_occurrence[x] = i

        # Initialize pointers
        ii = 0  # right boundary of current partition
        p = 0   # number of partitions

        # Iterate through the array
        for i, x in enumerate(nums):
            # Update the right boundary to include the last occurrence of current number
            ii = max(ii, last_occurrence[x])

            # If we reach the right boundary, we can end a partition here
            if ii == i:
                p += 1

        # The number of good partitions is 2^(p-1) because we can choose to split or not split at each boundary
        return pow(2, p - 1, MOD)

class Solution:
    def numberOfSets(self, n: int, maxDistance: int, roads: List[List[int]]) -> int:
        ans = 0
        # Iterate over all possible subsets of closed branches using bitmasks
        for mask in range(1 << n):
            # Initialize distance matrix with infinity
            g = [[float('inf')] * n for _ in range(n)]
            # Set distance from a node to itself as 0
            for i in range(n):
                g[i][i] = 0

            # Add roads between active branches (not closed)
            for u, v, w in roads:
                # Check if both branches are active (not closed)
                if not (mask & (1 << u)) and not (mask & (1 << v)):
                    # Update the distance matrix with minimum weight
                    g[u][v] = min(g[u][v], w)
                    g[v][u] = min(g[v][u], w)

            # Apply Floyd-Warshall algorithm to compute shortest paths
            for k in range(n):
                for i in range(n):
                    for j in range(n):
                        if g[i][k] != float('inf') and g[k][j] != float('inf'):
                            g[i][j] = min(g[i][j], g[i][k] + g[k][j])

            # Check if all active branches satisfy the maxDistance constraint
            ok = 1
            for i in range(n):
                for j in range(n):
                    # Only check pairs where both branches are active
                    if not (mask & (1 << i)) and not (mask & (1 << j)):
                        if g[i][j] > maxDistance:
                            ok = 0
                            break
                if ok == 0:
                    break

            # If all active branches satisfy the constraint, increment answer
            if ok:
                ans += 1

        return ans

class Solution:
    def countCompleteSubstrings(self, word: str, k: int) -> int:
        n = len(word)
        count = 0

        # Iterate through each starting position
        for i in range(n):
            # Use a frequency dictionary for current window
            freq = {}
            # Start sliding window from position i
            for j in range(i, n):
                # Check if adjacent characters differ by at most 2
                if j > i and abs(ord(word[j]) - ord(word[j-1])) > 2:
                    break

                # Add current character to frequency dictionary
                freq[word[j]] = freq.get(word[j], 0) + 1

                # Check if all characters in current window appear exactly k times
                valid = True
                for char in freq:
                    if freq[char] != k:
                        valid = False
                        break

                # If valid and window size is divisible by k (since each char appears k times)
                if valid and (j - i + 1) % k == 0:
                    # Check if number of distinct characters is such that each appears k times
                    distinct_count = len(freq)
                    if (j - i + 1) == distinct_count * k:
                        count += 1

        return count

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowels = {'a', 'e', 'i', 'o', 'u'}
        count = 0
        n = len(s)

        for i in range(n):
            vowels_count = 0
            consonants_count = 0
            for j in range(i, n):
                if s[j] in vowels:
                    vowels_count += 1
                else:
                    consonants_count += 1

                if vowels_count == consonants_count and (vowels_count * consonants_count) % k == 0:
                    count += 1

        return count

class Solution:
    def maximumStrongPairXor(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        max_xor = 0

        # Use sliding window with Trie
        trie = Trie()

        # Two pointers for sliding window
        left = 0
        for right in range(n):
            # Add current element to trie
            trie.insert(nums[right])

            # Remove elements from left that don't satisfy the condition
            # For nums[right], we need nums[left] >= nums[right] / 2
            while left < right and nums[left] < nums[right] / 2:
                trie.delete(nums[left])
                left += 1

            # Query maximum XOR with current element
            max_xor = max(max_xor, trie.query(nums[right]))

        return max_xor

class TrieNode:
    def __init__(self):
        self.children = {}
        self.count = 0  # Count of numbers passing through this node
        self.value = None  # Store the actual number if this is a leaf

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, num):
        node = self.root
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if bit not in node.children:
                node.children[bit] = TrieNode()
            node = node.children[bit]
            node.count += 1
        node.value = num  # Store the actual number at leaf

    def delete(self, num):
        node = self.root
        path = []
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            if bit in node.children:
                path.append((node, bit))
                node = node.children[bit]
                node.count -= 1
                if node.count == 0:
                    # Remove the node if count becomes 0
                    for parent, bit in reversed(path):
                        if parent.children[bit].count == 0:
                            del parent.children[bit]
                    return
        # If we reach here, the number wasn't found
        return

    def query(self, num):
        node = self.root
        max_xor = 0
        for i in range(31, -1, -1):
            bit = (num >> i) & 1
            # Try to go to the opposite bit to maximize XOR
            target_bit = 1 - bit
            if target_bit in node.children and node.children[target_bit].count > 0:
                node = node.children[target_bit]
                max_xor |= (1 << i)  # Set the i-th bit in result
            else:
                if bit in node.children and node.children[bit].count > 0:
                    node = node.children[bit]
                    # Don't set the i-th bit in result (it will be 0)
                else:
                    # No valid path, break
                    break

        # We need to actually compute the XOR value
        # The max_xor we computed is the maximum possible XOR value
        # But we need to verify it's achievable
        # Since we're using the greedy approach, it should be correct
        return max_xor

import heapq
from typing import List

class Solution:
    def maxSpending(self, values: List[List[int]]) -> int:
        r = []
        for shop in values:
            r.extend(shop)

        heapq.heapify(r)
        ans = 0
        for day in range(1, len(r) + 1):
            val = heapq.heappop(r)
            ans += val * day

        return ans

class Solution:
    def countSubMultisets(self, nums: List[int], l: int, r: int) -> int:
        MOD = 10**9 + 7

        # Count frequency of each element
        from collections import Counter
        freq = Counter(nums)

        # Initialize DP array
        dp = [0] * (r + 1)
        dp[0] = 1  # One way to make sum 0 (empty subset)

        # Process each unique number
        for num in freq:
            if num == 0:
                # Special case for zero - we can include it any number of times
                # But we need to be careful about the count
                count = freq[num]
                # For zero, we can include it 0, 1, ..., count times
                # This multiplies the number of ways by (count + 1)
                for i in range(r + 1):
                    if dp[i] > 0:
                        # We can add zero any number of times
                        # So we multiply the count by (count + 1)
                        dp[i] = (dp[i] * (count + 1)) % MOD
            else:
                # For non-zero numbers, we use the standard DP update
                # We need to update dp in reverse order to avoid using updated values
                temp = dp[:]  # Copy current state
                count = freq[num]

                # For each possible sum
                for k in range(r, -1, -1):
                    if temp[k] > 0:
                        # Add contributions from using 1, 2, ..., count of this number
                        for m in range(1, count + 1):
                            if k + m * num <= r:
                                dp[k + m * num] = (dp[k + m * num] + temp[k]) % MOD

        # Sum up all ways to make sums in range [l, r]
        result = 0
        for i in range(l, r + 1):
            result = (result + dp[i]) % MOD

        return result

class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        # Count the number of 1s in each bit position
        bit_count = [0] * 32

        for num in nums:
            for i in range(32):
                if num & (1 << i):
                    bit_count[i] += 1

        # Reconstruct numbers by greedily assigning 1s to highest positions
        # We want to create numbers with as many high bits as possible
        result = [0] * len(nums)

        # For each bit position from high to low, assign 1s to the numbers
        # We want to assign 1s to the numbers that will become the largest
        for i in range(31, -1, -1):
            # Assign bit i to the first bit_count[i] numbers
            # This ensures we create the largest possible numbers
            for j in range(bit_count[i]):
                result[j] |= (1 << i)

        # Sort in descending order to get the largest k numbers
        result.sort(reverse=True)

        # Take the sum of squares of the k largest numbers
        total = 0
        for i in range(k):
            total = (total + result[i] * result[i]) % MOD

        return total

class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        def get_square_free_part(n):
            # Get the square-free part of n
            # This is the product of primes with odd exponents in the prime factorization
            result = 1
            i = 2
            while i * i <= n:
                count = 0
                while n % i == 0:
                    count += 1
                    n //= i
                if count % 2 == 1:
                    result *= i
                i += 1
            if n > 1:
                result *= n
            return result

        # Group indices by their square-free parts
        groups = {}
        for i, num in enumerate(nums):
            square_free = get_square_free_part(num)
            if square_free not in groups:
                groups[square_free] = 0
            groups[square_free] += num

        # Return the maximum sum among all groups
        return max(groups.values())

class Solution:
    def countKSubsequencesWithMaxBeauty(self, s: str, k: int) -> int:
        MOD = 10**9 + 7

        # Count frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Get frequencies and sort in descending order
        frequencies = sorted(freq.values(), reverse=True)

        # If fewer than k distinct characters, return 0
        if len(frequencies) < k:
            return 0

        # Find the threshold frequency (k-th largest frequency)
        threshold = frequencies[k-1]

        # Count how many characters have frequency > threshold and == threshold
        count_greater = 0
        count_equal = 0

        for f in frequencies:
            if f > threshold:
                count_greater += 1
            elif f == threshold:
                count_equal += 1

        # We need to choose (k - count_greater) characters from the ones with frequency == threshold
        needed = k - count_greater

        # Calculate combination C(count_equal, needed)
        def combination(n, r):
            if r > n or r < 0:
                return 0
            if r == 0 or r == n:
                return 1

            # Use the property C(n, r) = C(n, n-r) to minimize computations
            r = min(r, n - r)
            result = 1
            for i in range(r):
                result = (result * (n - i)) // (i + 1)
            return result

        # Calculate the number of ways to choose the characters
        ways_to_choose = combination(count_equal, needed)

        # Calculate the product of frequencies for each selected character
        result = 1
        for f in frequencies:
            if f > threshold:
                result = (result * f) % MOD
            elif f == threshold:
                # We only multiply for the ones we choose
                pass

        # Multiply by the number of ways to choose the characters with threshold frequency
        result = (result * ways_to_choose) % MOD

        return result

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        # Check if total sum is less than target
        if sum(nums) < target:
            return -1

        # Count frequency of each power of 2
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        operations = 0
        bit = 0

        # Process each bit from 0 to 31 (since target < 2^31)
        while bit <= 31:
            # Check if current bit is set in target
            if target & (1 << bit):
                # If we have the required power of 2
                if freq.get(1 << bit, 0) > 0:
                    freq[1 << bit] -= 1
                else:
                    # Find the smallest larger power of 2 to split
                    found = False
                    for higher_bit in range(bit + 1, 32):
                        if freq.get(1 << higher_bit, 0) > 0:
                            # Split the higher power down to the required power
                            freq[1 << higher_bit] -= 1
                            # Add the split pieces
                            for i in range(higher_bit - bit):
                                freq[1 << (bit + i)] = freq.get(1 << (bit + i), 0) + 1
                            operations += higher_bit - bit
                            found = True
                            break

                    if not found:
                        return -1

            # Carry over unused powers to higher bits
            if bit < 31:
                # Combine pairs of current power to form next power
                count = freq.get(1 << bit, 0)
                freq[1 << (bit + 1)] = freq.get(1 << (bit + 1), 0) + count // 2
                # Keep remainder
                freq[1 << bit] = count % 2

            bit += 1

        return operations

class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count_up_to(n):
            if n == 0:
                return 0
            s = str(n)
            length = len(s)

            # dp[pos][tight][started][even_count][odd_count][rem]
            # pos: current position
            # tight: whether we are bounded by the prefix of n
            # started: whether we have started the number (avoid leading zeros)
            # even_count: count of even digits so far
            # odd_count: count of odd digits so far
            # rem: remainder modulo k
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, started, even_count, odd_count, rem):
                if pos == length:
                    # Check if the number is valid: equal even and odd digits and divisible by k
                    if started and even_count == odd_count and rem == 0:
                        return 1
                    return 0

                limit = int(s[pos]) if tight else 9
                total = 0

                for digit in range(0, limit + 1):
                    new_tight = tight and (digit == limit)
                    new_started = started or (digit > 0)
                    new_even_count = even_count
                    new_odd_count = odd_count
                    new_rem = (rem * 10 + digit) % k

                    if new_started:
                        if digit % 2 == 0:
                            new_even_count += 1
                        else:
                            new_odd_count += 1

                    total += dp(pos + 1, new_tight, new_started, new_even_count, new_odd_count, new_rem)

                return total

            return dp(0, True, False, 0, 0, 0)

        return count_up_to(high) - count_up_to(low - 1)

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total_imbalance = 0

        # Iterate over all possible subarrays
        for i in range(n):
            for j in range(i, n):
                # Extract subarray from index i to j
                subarray = nums[i:j+1]
                # Sort the subarray
                sorted_subarray = sorted(subarray)
                # Count imbalance numbers for this subarray
                imbalance = 0
                for k in range(len(sorted_subarray) - 1):
                    if sorted_subarray[k+1] - sorted_subarray[k] > 1:
                        imbalance += 1
                total_imbalance += imbalance

        return total_imbalance
